<div class="grid"><div class="field"><label>Task name</label><input name="task_name" value="{{ old('task_name', isset($task)?$task->task_name:'') }}" required></div><div class="field"><label>Due date</label><input type="date" name="due_date" value="{{ old('due_date', isset($task)?$task->due_date->format('Y-m-d'):'') }}" required></div><div class="field"><label>Status</label><select name="status"><option value="Pending">Pending</option><option value="Completed" @if(old('status',isset($task)?$task->status:'')==='Completed') selected @endif>Completed</option></select></div><div class="field full"><label>Description</label><textarea name="description">{{ old('description', isset($task)?$task->description:'') }}</textarea></div></div><br>
